// ---- story (chapter Ch3 part 3a, ch3a agent: Sapphire's story scripts of this room; generators must keep
// everything from this line on; entries above marked "// story:")
// Sapphire data/maps/SlateportCity_House1/scripts.inc: the Name Rater, with Black 2's own Name Rater commands (file
// 1233: CallPokeSelect, PokePartyIsEgg, PokePartyIsOriginGame for "is the player its Trainer", CallPokeNameInput).
// Sapphire's TV_PutNameRaterShowOnTheAir... only answers "did the name change" here (Black 2 has no TV shows).
// data/story/ch3a.json. Lines 2-10 of the text file.
#define T_Pleased 2
#define T_Critique 3
#define T_VisitAgain 4
#define T_FineName 5
#define T_Egg 6
#define T_Magnificent 7
#define T_NewName 8
#define T_NoDifferent 9
#define T_KnownAs 10

Story_NR_NameRater:                         // SlateportCity_NameRatersHouse_EventScript_NameRater
    c3_talk
    h_yesno T_Pleased, C3_TMP
    h_goto_if_no C3_TMP, L_NR_Decline
    h_msgbox T_Critique                     // ..._ChooseMonToRate
    h_closemessage
    CallPokeSelect 0, C3_TMP, C3_LEAD, 0    // special SelectMonForNPCTrade (C3_TMP 0 = cancelled)
    h_goto_if_eq C3_TMP, 0, L_NR_Decline
    PokePartyIsEgg C3_TMP, C3_LEAD          // ..._RateMonNickname: SPECIES_EGG?
    h_goto_if_eq C3_TMP, 1, L_NR_Egg
    WordSetPartyPokeName 1, C3_LEAD         // TV_CopyNicknameToStringVar1AndEnsureTerminated
    PokePartyIsOriginGame C3_TMP, C3_LEAD   // TV_CheckMonOTIDEqualsPlayerID / MonOTNameMatchesPlayer (0 = not yours)
    h_goto_if_eq C3_TMP, 0, L_NR_NotOT
    h_yesno T_FineName, C3_TMP
    h_goto_if_no C3_TMP, L_NR_Decline
    h_msgbox T_NewName                      // ..._ChangeNickname
    h_closemessage
    CallPokeNameInput C3_TMP, C3_LEAD, 1    // Common_EventScript_NameReceivedPartyMon, as Black 2's Name Rater calls it
    WordSetPartyPokeName 1, C3_LEAD
    h_goto_if_ne C3_TMP, 0, L_NR_NewNameDifferent   // 1 = the nickname changed
    h_msgbox T_NoDifferent
    h_release
L_NR_NewNameDifferent:
    h_msgbox T_KnownAs
    h_release
L_NR_Decline:
    h_msgbox T_VisitAgain
    h_release
L_NR_Egg:
    h_msgbox T_Egg
    h_release
L_NR_NotOT:
    h_msgbox T_Magnificent
    h_release
    .balign 4, 0
